// The catalog's default view (no search, no category filter) shows only
// these, in this order, rather than the full catalog at once — a
// hiring-manager skim shouldn't have to work through every component to
// see the range on offer. Picked for category breadth and documentation
// depth (mostly "Verified" entries, which carry the richest overrides
// above), plus one deliberate callback: Command Card is the same
// component the hero's own "Executive overview" card is built from.
// Filtering by search or category still searches/shows the complete
// catalog — this only narrows the unfiltered "All" view.
const FEATURED_IDS = [
  "command-card",
  "kpi-card",
  "data-table",
  "file-upload",
  "calendar",
  "mega-menu"
];

const components = raw.map(([title, category, maturity], i) => {
  const id = title.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  const base = baseByCategory[category];
  const spec = overrides[id] || {};
  return {
    id,
    title,
    category,
    maturity,
    color: ["#168326", "#0F6CBD", "#5B5BD6", "#C239B3", "#D83B01"][i % 5],
    // Every override with real property/event/architecture detail gets
    // its own one-line summary now too — without spec.summary here,
    // even a component with a fully bespoke contract still showed this
    // same generic sentence, identical to every other component in its
    // category, on its card and Preview tab.
    summary: spec.summary || `A reusable ${category.toLowerCase()} pattern designed for responsive, governed enterprise Power Platform experiences.`,
    properties: spec.properties || base.properties,
    events: spec.events || base.events,
    architecture: spec.architecture || base.architecture,
    examples: spec.examples || base.examples,
    accessibility: spec.accessibility || base.accessibility,
    limitations: spec.limitations || base.limitations,
    variants: spec.variants || GENERIC_VARIANTS,
    // Most of the catalog's "Copy YAML" only ever exports the property/
    // event contract — real, schema-valid, but no Children:, so a
    // Studio paste creates an empty canvas with that contract wired up
    // and nothing visible. CHILDREN_BUILDERS lists the components that
    // now also export a real control tree (componentChildren.js) — see
    // .claude/skills/power-app-component-writer/SKILL.md for which
    // control types and properties are actually confirmed real — so
    // yamlStatus says exactly that instead of the same disclaimer every
    // other still-contract-only component carries.
    yamlStatus: CHILDREN_BUILDERS[title]
      ? "Property/event contract plus a real visual control tree (GroupContainer/ModernText/Image/Classic-Button, plus Timer for an animated pulse) — pastes as an actual visible component, not just the property scaffold"
      : maturity === "Verified"
      ? "Property and event contract cross-checked against a published reference component; this project's own YAML source is drafted but not yet Studio-tested"
      : "Design specification only; executable YAML not yet built or verified"
  };
});

export { categories, icons, components, FEATURED_IDS };
